import html.parser, sys
class P(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack=[]
        self.errors=[]
    def handle_starttag(self,tag,attrs):
        if tag not in ('meta','link','br','hr','img','input','source','wbr'):
            self.stack.append(tag)
    def handle_endtag(self,tag):
        if not self.stack:
            self.errors.append(f'closing {tag} with empty stack')
            return
        if self.stack[-1]==tag:
            self.stack.pop()
        else:
            self.errors.append(f'mismatch: open={self.stack[-1]} close={tag}')
p=P()
